#!/usr/bin/env python3
"""Tiny MCP stdio-less client for the local Figma Dev Mode MCP server."""
import json
import os
import sys
import urllib.request

URL = os.environ.get("MCP_URL", "http://127.0.0.1:3845/mcp")
SESSION = os.environ["MCP_SESSION"]


def call(method: str, params: dict) -> dict:
    body = json.dumps({"jsonrpc": "2.0", "id": 1, "method": method, "params": params}).encode()
    req = urllib.request.Request(URL, data=body, method="POST")
    req.add_header("Content-Type", "application/json")
    req.add_header("Accept", "application/json, text/event-stream")
    req.add_header("Mcp-Session-Id", SESSION)
    with urllib.request.urlopen(req, timeout=120) as resp:
        raw = resp.read().decode()
    if raw.startswith("event:") or "\ndata:" in raw:
        for line in raw.splitlines():
            if line.startswith("data:"):
                raw = line[5:].strip()
                break
    return json.loads(raw)


def main() -> None:
    method = sys.argv[1]
    params = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
    print(json.dumps(call(method, params), ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

