from decimal import Decimal
from pydantic import BaseModel, field_validator, ValidationError
from pydantic_core import PydanticCustomError

class M(BaseModel):
    price: Decimal
print("decimal json:", M(price=Decimal("26.00")).model_dump_json())

class R(BaseModel):
    x: str
    @field_validator("x")
    @classmethod
